import { sql } from 'drizzle-orm';
import { timestamp, uuid } from 'drizzle-orm/pg-core';
import { INDIAN_MOBILE_E164_PATTERN } from '@mom/shared';

/**
 * Primary key for rows that are exposed in URLs / QR codes / the API.
 * UUIDv7 is time-ordered, so inserts stay at the end of the index (no fragmentation
 * like random UUIDv4) while still carrying 74 random bits.
 * Generated by the database (`uuid_generate_v7()`, migration 0000) so every insert path
 * — app, seed, admin SQL — gets one. On PostgreSQL 18+ this can become the built-in uuidv7().
 */
export const publicId = () =>
  uuid()
    .primaryKey()
    .default(sql`uuid_generate_v7()`);

export const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

export const updatedAt = () =>
  timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

/** Indian mobile number in E.164 form (shared with the API and web app). */
export const INDIAN_PHONE_REGEX = INDIAN_MOBILE_E164_PATTERN;
